        const names = [(await env.DB.prepare('SELECT name FROM families WHERE id=?').bind(a.family_id).first()).name, ...(await env.DB.prepare('SELECT name FROM collectors WHERE family_id=?').bind(a.family_id).all()).results.map(x => x.name)].map(n => n.toLowerCase());
